(function(){
'use strict';
const {lessons,stages,glossary}=window.FXCourse;
const L=window.FXLogic;
const STORAGE=window.PipwiseCloud?.storageKey || 'pipwise_academy_v1';
const VIEWS=['dashboard','academy','lab','calculator','journal','analytics','assessment','glossary','settings','admin'];
const navItems=[['dashboard','Overview','home'],['academy','Learn Forex','book'],['lab','Practice Terminal','chart'],['calculator','Risk Calculator','calculator'],['journal','Trade Journal','notes'],['analytics','Performance','activity'],['assessment','Mastery Check','award'],['glossary','Forex Dictionary','search'],['settings','Your Data','settings'],...(window.PipwiseCloud?.isAdmin ? [['admin','Administrator','shield']] : [])];
const ic={home:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',book:'<path d="M4 19.5A2.5 2.5 0 016.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 014 19.5v-15A2.5 2.5 0 016.5 2z"/>',chart:'<path d="M3 3v18h18"/><path d="m6 15 4-4 3 3 6-7"/>',calculator:'<rect x="5" y="2" width="14" height="20" rx="2"/><path d="M8 6h8M8 11h2m4 0h2M8 15h2m4 0h2M8 19h2m4 0h2"/>',notes:'<path d="M8 3H5a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-3M8 3v5h5M8 3l5 5M9 14h6m-6 4h4"/><path d="m13 8 6-6 3 3-6 6-4 1z"/>',activity:'<path d="M2 12h4l3-8 4 16 3-8h6"/>',award:'<circle cx="12" cy="8" r="5"/><path d="m8.5 12-2 9L12 18l5.5 3-2-9"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M4.9 4.9l2.1 2.1m10 10 2.1 2.1m0-14.2L17 7m-10 10-2.1 2.1"/>',check:'<path d="m4 12 5 5L20 6"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/><path d="m9 12 2 2 4-4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 18v3h16v-3"/>'};
const icon=(n)=>`<svg aria-hidden="true" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8">${ic[n]||ic.home}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]));
const fmt=L.money;
const pct=n=>`${L.round(n,1)}%`;
const defaults=()=>({version:1,completed:{},plan:'',balance:10000,balanceHistory:[10000],trades:[],open:null,market:{pair:'EUR/USD',scenario:'Uptrend',mode:'synthetic',seed:101,index:85},imported:null,sessionStart:10000,sessionPnL:0,exam:null});
function load(){try{const x=JSON.parse(localStorage.getItem(STORAGE)||'null');if(!x || x.version!==1 || !Array.isArray(x.trades) || !x.market || !L.PAIRS[x.market.pair] || !L.SCENARIOS.includes(x.market.scenario))return defaults();return {...defaults(),...x};}catch{return defaults();}}
let data=load();
let view='dashboard',selectedLesson=lessons.find(l=>!data.completed[l.id])?.id||lessons[0].id;
let quizDraft={},quizFeedback={},examQuestions=[],examDraft={},examFeedback=null,glossaryTerm='',currentJournalFilter='all';
const marketCache={key:null,candles:null};
let toastTimeout=null;
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(data));window.PipwiseCloud?.queueSync?.(data);}catch{toast('Browser storage is full. Export your progress.');}}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove('show'),3800);}
function getCandles(){if(data.market.mode==='csv' && data.imported?.candles?.length)return data.imported.candles;const key=[data.market.pair,data.market.scenario,data.market.seed].join('/');if(key!==marketCache.key){marketCache.key=key;marketCache.candles=L.generateMarket(data.market.pair,data.market.scenario,data.market.seed);}return marketCache.candles;}
const candle=()=>getCandles()[data.market.index];
const spread=()=>data.market.mode==='csv'?L.PAIRS[data.market.pair].spread:L.spreadAt(data.market.pair,data.market.scenario,data.market.index);
const quote=()=>L.quote(candle().close,data.market.pair,spread());
const floating=()=>L.floatingPL(data.open,candle().close,spread());
const equity=()=>L.round(data.balance+floating());
const perf=()=>L.evaluatePerformance(data.trades,data.balanceHistory);
const passed=()=>lessons.filter(l=>(data.completed[l.id]||0)>=75).length;
const studyPct=()=>L.round(passed()/lessons.length*100);
const sessionHalt=()=>data.sessionPnL <= -0.02*data.sessionStart;
const valueClass=n=>n>0?'green':n<0?'red-text':'';
function setView(to){if(!VIEWS.includes(to))return;view=to;render();window.scrollTo({top:0,behavior:'instant'});}
function shell(content){let totalMinutes=lessons.reduce((a,l)=>a+l.minutes,0);
  return `<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-icon">P<span style="font-size:16px">/</span></div><div><strong>pipwise<span class="accent">.</span></strong><small>FOREX ACADEMY</small></div></div><nav class="sidebar-nav" aria-label="Main navigation"><div class="nav-label">Your workspace</div>${navItems.map(([id,name,i],idx)=>`${idx===6?'<div class="nav-label">Resources</div>':''}<button class="nav-btn ${view===id?'active':''}" data-nav="${id}" ${view===id?'aria-current="page"':''}>${icon(i)}<span>${name}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="mini-note"><strong>TRAINING MODE ONLY</strong>Price charts are synthetic. Nothing here connects to a real broker or handles money.<div class="sidebar-progress"><span style="width:${studyPct()}%"></span></div>${passed()} of 20 lessons passed · ${totalMinutes} minutes of guided material</div></div></aside><main class="workspace"><header class="topbar"><div><div class="eyebrow" style="margin-bottom:3px">Your personal trading school</div><div class="context">Knowledge first. Capital protection always.</div></div><div class="topright"><span class="status-pill" id="cloudIndicator">${window.PipwiseCloud?.mode==='cloud'?'Cloud: checking':'Local practice'}</span><span class="chip teal">${passed()}/20 lessons</span><button class="btn ghost sm" data-action="logout">${window.PipwiseCloud?.mode==='cloud'?'Sign out':'Accounts'}</button></div></header>${content}<footer class="footer">Pipwise is an educational, offline simulator. Quotes and candles are generated, not sourced from the live market. Training results do not predict real trading. No real orders or funds.</footer></main></div>`;
}
function metric(label,n,detail,ico='activity'){return `<div class="card metric"><div class="metric-icon">${icon(ico)}</div><div class="number t-num">${n}</div><div class="label">${label}</div><div class="detail">${detail}</div></div>`;}
function dashboard(){const st=perf(); const next=lessons.find(l=>!data.completed[l.id])||lessons[0];const latest=data.trades.slice(-4).reverse();
return `<section class="hero"><div class="eyebrow">Welcome to the academy</div><h1>Learn the skill.<br><span class="accent">Protect the capital.</span></h1><p class="lead">Go from complete beginner to a structured demo trading process. Learn with worked examples, test your knowledge, then practice managing realistic order mechanics on synthetic prices.</p><div class="hero-actions"><button class="btn" data-nav="academy">${icon('book')} ${passed()? 'Continue learning' : 'Start lesson one'} ${icon('arrow')}</button><button class="btn secondary" data-nav="lab">${icon('chart')} Open practice terminal</button></div></section>
<div class="grid grid-4">${metric('Lessons passed',`${passed()} / 20`,`${studyPct()}% curriculum completion`,'book')}${metric('Demo account equity',fmt(equity()),'Synthetic USD practice balance','shield')}${metric('Completed demo trades',st.count,'Journal each trade to learn','chart')}${metric('Journal completion',`${st.journalRate}%`,'Post-trade reflections with 15+ characters','notes')}</div>
<div class="section-heading"><div><h2>Your learning path</h2><p class="muted">Twenty lessons across five skill stages. Each lesson ends with a four-question quiz.</p></div><span class="chip teal">75% to pass lessons</span></div><div class="grid grid-3">${stages.map((s,i)=>{const done=lessons.filter(l=>l.stage===i&&data.completed[l.id]).length;return `<div class="card section-card"><div class="top"><span class="stage-count">${esc(s.name)}</span><span class="chip ${done===4?'teal':''}">${done}/4</span></div><h3>${esc(s.short)}</h3><p class="stage-desc">${esc(s.desc)}</p><div class="progress-track"><div class="fill" style="width:${done/4*100}%"></div></div><button class="btn ghost sm stage-card-action" data-stage="${i}">${done===4?'Review lessons':'Study this stage'} ${icon('arrow')}</button></div>`;}).join('')}</div>
<div class="section-heading"><div><h2>Next steps</h2><p class="muted">Keep lesson knowledge and trading discipline separate.</p></div></div><div class="grid grid-2"><div class="card"><span class="chip teal">NEXT LESSON</span><h3 style="margin-top:14px">${esc(next.title)}</h3><p class="muted">${esc(next.summary)}</p><div class="inline-actions"><span class="caption">${next.minutes}-minute lesson</span><button class="btn sm" data-lesson="${next.id}">Open lesson ${icon('arrow')}</button></div></div><div class="card"><span class="chip orange">READINESS CHECK</span><h3 style="margin-top:14px">A badge is not a trading license.</h3><p class="muted">Complete lessons, review demo trades, and pass the final assessment. Then continue testing with a regulated broker's real-market demo before considering real funds.</p><button class="btn secondary sm" data-nav="assessment">View mastery milestones ${icon('arrow')}</button></div></div>
<div class="section-heading"><div><h2>Your written rules</h2><p class="muted">Write a measurable plan. Your rules save to your account when cloud sign-in is active.</p></div></div><div class="card"><div class="grid grid-2"><div><div class="field"><label for="planInput">Your setup, timeframe, risk limit, and no-trade conditions</label><textarea id="planInput" rows="5" placeholder="Example: I practice EUR/USD on the 1-hour chart. I risk 0.5% per trade. I skip high-impact news and require a written stop, target, and entry trigger.">${esc(data.plan)}</textarea></div><button class="btn sm" data-action="save-plan" style="margin-top:12px">Save my trading plan</button></div><div class="callout"><strong>Discipline rule</strong><p style="margin-top:10px">A good trading day does not require placing a trade. Protecting your account when no valid setup appears counts as success.</p><span class="caption">Your plan is used in the final readiness checklist.</span></div></div></div>
${latest.length?`<div class="section-heading"><h2>Recent practice trades</h2></div><div class="card table-wrap"><table><thead><tr><th>Side</th><th>Pair</th><th>Result</th><th>Exit</th></tr></thead><tbody>${latest.map(t=>`<tr><td>${t.side}</td><td>${t.pair}</td><td class="${valueClass(t.pnl)}">${fmt(t.pnl)}</td><td>${esc(t.reason)}</td></tr>`).join('')}</tbody></table></div>`:''}`;
}
function academy(){const les=lessons.find(l=>l.id===selectedLesson)||lessons[0],li=lessons.indexOf(les);const choice=quizDraft[les.id]||{}, feedback=quizFeedback[les.id];return `<div class="section-heading" style="margin-top:0"><div><div class="eyebrow">Full curriculum</div><h1>Learn one concept at a time.</h1><p class="muted">Read. Practice. Answer four questions. Retake anything you miss.</p></div><span class="chip teal">${passed()} passed</span></div><div class="academy-layout"><aside class="card lesson-list" aria-label="Course lessons">${stages.map((s,i)=>`<div class="lesson-stage">${esc(s.name)}</div>${lessons.filter(l=>l.stage===i).map(l=>{const ix=lessons.indexOf(l);return `<button class="lesson-link ${l.id===selectedLesson?'active':''} ${data.completed[l.id]?'passed':''}" data-lesson="${l.id}"><span class="index">${data.completed[l.id]?icon('check'):String(ix+1).padStart(2,'0')}</span><span>${esc(l.title)}<small>${l.minutes} min · ${data.completed[l.id]?'Passed '+data.completed[l.id]+'%':'Quiz pending'}</small></span></button>`;}).join('')}`).join('')}</aside><div class="card" style="min-width:0"><div class="lesson-header"><div class="inline-actions"><span class="chip teal">STAGE ${les.stage+1}</span><span class="chip">LESSON ${li+1} OF 20</span><span class="chip">${les.minutes} MIN</span></div><h2>${esc(les.title)}</h2><p class="lesson-lead">${esc(les.summary)}</p></div><h3 style="margin-bottom:17px">What you need to understand</h3><ol class="concept-list">${les.points.map((p,i)=>`<li><span>${i+1}</span><div>${esc(p)}</div></li>`).join('')}</ol><div class="example"><h4 style="margin-bottom:9px;color:var(--blue)">Worked example</h4><p>${esc(les.example)}</p></div><div class="example amber"><h4 style="margin-bottom:9px;color:var(--amber)">Practice assignment</h4><p>${esc(les.task)}</p></div><div class="quiz"><div class="inline-actions" style="justify-content:space-between"><div><div class="eyebrow">Knowledge check</div><h3>Prove what you learned</h3></div><span class="chip">Pass with 3 of 4</span></div>${les.questions.map((q,i)=>{const sel=choice[i];return `<div class="question"><h4>${i+1}. ${esc(q.question)}</h4><div class="options">${q.answers.map((a,j)=>{const review=feedback!==undefined; const state=review && j===q.correct?'right': review&&sel===j&&j!==q.correct?'wrong':sel===j?'chosen':'';return `<button class="option ${state}" data-answer-lesson="${les.id}" data-q="${i}" data-opt="${j}" ${review?'disabled':''}>${String.fromCharCode(65+j)}. ${esc(a)}</button>`;}).join('')}</div>${feedback!==undefined?`<p class="rationale">${sel===q.correct?'Correct. ':'Review. '}${esc(q.why)}</p>`:''}</div>`;}).join('')}${feedback===undefined?`<button class="btn" data-action="submit-quiz" data-id="${les.id}">Grade my answers ${icon('arrow')}</button>`:`<div class="result-box"><strong class="${feedback>=75?'accent':'warning'}">${feedback}% · ${feedback>=75?'Lesson passed':'Review and retry'}</strong><p class="muted">${feedback>=75?'Your result was saved to your progress.':'Review each explanation and try again.'}</p><div class="inline-actions"><button class="btn secondary sm" data-action="retry-quiz" data-id="${les.id}">Retake quiz</button>${li<lessons.length-1?`<button class="btn sm" data-lesson="${lessons[li+1].id}">Next lesson ${icon('arrow')}</button>`:''}</div></div>`}</div><div class="divider"></div><div class="inline-actions" style="justify-content:space-between"><button class="btn ghost sm" ${li===0?'disabled':''} data-lesson="${lessons[Math.max(0,li-1)].id}">Previous lesson</button><button class="btn ghost sm" ${li===lessons.length-1?'disabled':''} data-lesson="${lessons[Math.min(lessons.length-1,li+1)].id}">Next lesson</button></div></div></div>`;}
function tradePreview(side,riskPct,stop,target){const pos=L.positionSize(equity(),riskPct,stop,data.market.pair);if(!pos)return null;const entry=side==='BUY'?quote().ask:quote().bid;const margin=L.round(pos.lots*100000*entry/20);return {...pos,side,entry,margin,stop,target,potentialReward:L.round(target*L.pipValue(pos.lots,data.market.pair))};}
function lab(){const c=candle(),qte=quote(),st=perf(),current=data.open,limit=sessionHalt(); const closed=data.market.index>=getCandles().length-1;return `<div class="section-heading" style="margin-top:0"><div><div class="eyebrow">Risk-first practice lab</div><h1>Trade the process. Not a prediction.</h1><p class="muted">Reveal candles step by step. Choose generated training prices or import historical OHLC data.</p></div><span class="chip orange">${data.market.mode==='csv'?'IMPORTED PRICES / MODELED COSTS':'SYNTHETIC PRICES'}</span></div><div class="stat-strip"><div><small>Demo equity</small><strong class="t-num">${fmt(equity())}</strong></div><div><small>Realized balance</small><strong class="t-num">${fmt(data.balance)}</strong></div><div><small>Floating P&L</small><strong class="${valueClass(floating())} t-num">${fmt(floating())}</strong></div><div><small>Session P&L</small><strong class="${valueClass(data.sessionPnL)} t-num">${fmt(data.sessionPnL)}</strong></div></div><div class="lab-layout"><div class="lab-left"><div class="card"><div class="lab-controls"><label class="field" style="gap:3px"><span class="caption">PAIR (USD QUOTE)</span><select id="marketPair" aria-label="Practice currency pair" ${current?'disabled':''}>${Object.keys(L.PAIRS).map(p=>`<option ${p===data.market.pair?'selected':''}>${p}</option>`).join('')}</select></label><label class="field" style="gap:3px"><span class="caption">DATA SOURCE</span><select id="marketSource" aria-label="Market data source" ${current?'disabled':''}><option value="synthetic" ${data.market.mode!=='csv'?'selected':''}>Synthetic</option><option value="csv" ${data.market.mode==='csv'?'selected':''}>Historical CSV</option></select></label><label class="field" style="gap:3px"><span class="caption">TRAINING REGIME</span><select id="marketScenario" aria-label="Market simulation scenario" ${current?'disabled':''}>${L.SCENARIOS.map(s=>`<option ${s===data.market.scenario?'selected':''}>${s}</option>`).join('')}</select></label><button class="btn secondary sm" data-action="new-scenario" ${current?'disabled':''}>Start selected session</button></div><div class="inline-actions" style="justify-content:space-between;margin:9px 0"><div><div class="caption">${esc(L.PAIRS[data.market.pair].name)} · Candle ${data.market.index+1}/${getCandles().length}</div><div class="lab-price t-num">${c.close.toFixed(5)}</div></div><div class="chip">Spread ${spread().toFixed(1)} pips</div></div><div class="chart-frame"><canvas id="priceChart" role="img" aria-label="Synthetic candlestick chart showing recent prices, exponential moving averages, and trade levels"></canvas></div><div class="chart-legend"><span><i class="dot teal"></i> Up candle / EMA 20</span><span><i class="dot blue"></i> EMA 50</span><span><i class="dot orange"></i> Entry or target</span></div><div class="controls-row"><button class="btn" data-action="next-bar" data-count="1" ${closed?'disabled':''}>Next candle ${icon('arrow')}</button><button class="btn secondary" data-action="next-bar" data-count="10" ${closed?'disabled':''}>Advance 10 candles</button><span class="caption">No look-ahead. One open trade maximum.</span></div>${closed?`<p class="warning" style="margin:13px 0">End of generated scenario. Start a new session to continue.</p>`:''}${limit?`<div class="callout red" style="margin-top:15px"><strong>Session risk stop reached</strong><p>The realized session loss met the 2% training threshold. New entries remain paused until your next practice session.</p></div>`:''}</div><div class="card" style="margin-top:18px"><h3>Replay your own historical CSV</h3><p class="notice">Upload an OHLC CSV with headers <code>open, high, low, close</code> and 100 to 2,000 candles, ordered oldest to newest. Select the matching pair above, then start a Historical CSV session. Files stay in this browser. Imported OHLC prices are provided by you. Spread and fill costs remain simplified simulations.</p><div class="inline-actions"><label class="btn secondary sm" for="csvFile">Import historical OHLC CSV</label><input id="csvFile" type="file" accept=".csv,text/csv" style="position:absolute;width:1px;height:1px;overflow:hidden;opacity:0" ${current?'disabled':''}/>${data.imported?`<span class="chip teal">${esc(data.imported.name)} · ${data.imported.candles.length} bars · ${esc(data.imported.pair)}</span>`:'<span class="caption">No historical file imported</span>'}</div></div><div class="card" style="margin-top:18px"><h3>How the simulation fills orders</h3><p class="notice">BUY opens at ask and closes at bid. SELL opens at bid and closes at ask. If a candle touches both stop and target, the stop wins. A simulated 1-pip adverse stop slippage applies in the News shock regime. Overnight financing, commissions, actual liquidity, and broker liquidation are not modeled. This is training data, not a profitability backtest.</p></div></div><div class="lab-right"><div class="card order-panel"><div class="inline-actions" style="justify-content:space-between"><h3>Place a practice order</h3><span class="chip teal">Risk ≤ 1%</span></div><div class="pair-price"><div><small>SELL / BID</small><strong class="red-text t-num">${qte.bid.toFixed(5)}</strong></div><div><small>BUY / ASK</small><strong class="green t-num">${qte.ask.toFixed(5)}</strong></div></div><div class="form-grid"><div class="field"><label for="orderRisk">Account risk (%)</label><select id="orderRisk" ${current||limit||closed?'disabled':''}><option value="0.25">0.25%</option><option value="0.5" selected>0.50%</option><option value="1">1.00%</option></select></div><div class="field"><label for="orderStop">Stop distance (pips)</label><input id="orderStop" type="number" value="25" min="5" max="250" step="1" ${current||limit||closed?'disabled':''}/></div><div class="field"><label for="orderTarget">Target distance (pips)</label><input id="orderTarget" type="number" value="50" min="5" max="500" step="1" ${current||limit||closed?'disabled':''}/></div><div class="field"><label for="orderSidePreview">Preview direction</label><select id="orderSidePreview" ${current||limit||closed?'disabled':''}><option>BUY</option><option>SELL</option></select></div></div><div id="orderSizing" class="order-summary"></div><div class="field"><label for="tradeThesis">Your reason for entering (at least 12 characters)</label><textarea id="tradeThesis" placeholder="Example: In a higher-high trend, price pulled back to an earlier support zone and held." ${current||limit||closed?'disabled':''}></textarea></div><p class="checklist-title" style="margin-top:13px">Mandatory pretrade checklist</p><label class="check-item"><input type="checkbox" id="ruleSetup" ${current||limit||closed?'disabled':''}/> I identified a specific setup and entry trigger.</label><label class="check-item"><input type="checkbox" id="ruleEvent" ${current||limit||closed?'disabled':''}/> I checked event risk in this training scenario.</label><label class="check-item"><input type="checkbox" id="ruleRisk" ${current||limit||closed?'disabled':''}/> I accept the planned stop and dollar loss.</label><div class="two-way" style="margin-top:17px"><button data-action="open-trade" data-side="BUY" ${current||limit||closed?'disabled':''}>BUY / LONG</button><button class="sell" data-action="open-trade" data-side="SELL" ${current||limit||closed?'disabled':''}>SELL / SHORT</button></div><p class="caption" style="margin:11px 0 0">The model sizes in 0.01 lot steps and checks initial margin at a training limit of 20:1.</p></div><div class="card position-panel"><h3>Open position</h3>${current?`<div class="inline-actions"><span class="chip ${current.side==='BUY'?'teal':'red'}">${current.side}</span><span class="chip">${current.pair}</span></div><div class="kv"><span>Size / Entry</span><strong>${current.lots.toFixed(2)} lot · ${current.entry.toFixed(5)}</strong></div><div class="kv"><span>Stop / Target</span><strong>${current.sl.toFixed(5)} / ${current.tp.toFixed(5)}</strong></div><div class="kv"><span>Planned risk</span><strong>${fmt(current.risk)}</strong></div><div class="kv"><span>Margin used (20:1)</span><strong>${fmt(current.margin)}</strong></div><div class="kv"><span>Floating result</span><strong class="${valueClass(floating())}">${fmt(floating())}</strong></div><p class="notice" style="margin:11px 0">${esc(current.thesis)}</p><button class="btn secondary full" data-action="close-trade">Close at executable quote</button>`:`<div class="empty">No open position.<p style="margin:7px 0 0">Complete your checklist before entering a trade.</p></div>`}</div></div></div>`;}
function calculator(){return `<div class="section-heading" style="margin-top:0"><div><div class="eyebrow">Practical trading math</div><h1>Know the loss before the lot size.</h1><p class="muted">Risk sizing for major pairs quoted in USD, with a USD-denominated account.</p></div></div><div class="grid grid-2"><div class="card"><h3>Position-size calculator</h3><p class="muted">A calculator helps implement an existing risk decision. It does not identify a profitable entry.</p><div class="form-grid"><div class="field"><label for="calcBalance">Account equity (USD)</label><input id="calcBalance" type="number" min="1" value="10000" step="100"></div><div class="field"><label for="calcPct">Risk per trade (%)</label><select id="calcPct"><option value="0.25">0.25%</option><option value="0.5" selected>0.50%</option><option value="1">1.00%</option></select></div><div class="field"><label for="calcStop">Stop distance (pips)</label><input id="calcStop" type="number" min="1" max="2000" value="25"></div><div class="field"><label for="calcPair">Currency pair</label><select id="calcPair">${Object.keys(L.PAIRS).map(p=>`<option>${p}</option>`).join('')}</select></div></div><div class="example" style="margin-bottom:0"><strong>Formula</strong><p style="margin-top:9px">Risk dollars = equity × risk percentage. Lots = risk dollars ÷ (stop pips × $10 per standard lot). Round down to 0.01 lot.</p></div></div><div class="calc-output" id="calcResults" aria-live="polite"></div></div><div class="section-heading"><h2>Examples you should know</h2></div><div class="grid grid-3"><div class="card"><div class="eyebrow">Case A</div><h3>$10,000 account</h3><p class="muted">0.5% risk · 25 pip stop</p><p><strong>0.20 lots</strong> = $50 planned stop loss.</p></div><div class="card"><div class="eyebrow">Case B</div><h3>$3,000 account</h3><p class="muted">0.5% risk · 30 pip stop</p><p><strong>0.05 lots</strong> = $15 planned stop loss.</p></div><div class="card"><div class="eyebrow">Case C</div><h3>$1,000 account</h3><p class="muted">0.25% risk · 40 pip stop</p><p><strong>Skip trade</strong> if the minimum 0.01 lot exceeds $2.50 risk.</p></div></div><div class="callout amber" style="margin-top:20px"><strong>Calculator assumptions</strong><p style="margin-top:8px">EUR/USD, GBP/USD, AUD/USD, and NZD/USD all have USD as the quote currency, so one standard lot is worth $10 per pip. Real markets involve variable spread, commissions, slippage, and financing. For crosses and JPY pairs, a different conversion formula is required. This calculator intentionally excludes those pairs.</p></div>`;}
function journal(){const filtered=data.trades.filter(t=>currentJournalFilter==='all'||(currentJournalFilter==='reviewed'? (t.reflection||'').trim().length>=15:(t.reflection||'').trim().length<15)).slice().reverse();return `<div class="section-heading" style="margin-top:0"><div><div class="eyebrow">Behavior creates the evidence</div><h1>Your trade journal.</h1><p class="muted">Record why you entered, how you exited, and whether the process was followed.</p></div><span class="chip teal">${perf().journalled}/${data.trades.length} reviewed</span></div><div class="callout"><strong>What to write after every trade</strong><p style="margin-top:8px">Was the entry justified? Did you obey the original stop and target? What will you repeat or change? Describe the process independently from the money won or lost.</p></div><div class="inline-actions" style="margin:22px 0 12px"><button class="btn ${currentJournalFilter==='all'?'':'secondary'} sm" data-filter="all">All trades</button><button class="btn ${currentJournalFilter==='pending'?'':'secondary'} sm" data-filter="pending">Needs reflection</button><button class="btn ${currentJournalFilter==='reviewed'?'':'secondary'} sm" data-filter="reviewed">Reviewed</button></div>${!filtered.length?`<div class="empty">No trades in this view. <button class="btn sm" data-nav="lab">Open terminal</button></div>`:`<div class="grid">${filtered.map(t=>`<article class="card"><div class="inline-actions" style="justify-content:space-between"><div class="inline-actions"><span class="chip ${t.side==='BUY'?'teal':'red'}">${t.side}</span><strong>${t.pair}</strong><span class="caption">${esc(t.scenario)} · ${esc(t.date)}</span></div><h3 class="${valueClass(t.pnl)}">${fmt(t.pnl)} <span class="caption">(${L.round(t.pnl/t.risk,2)}R)</span></h3></div><div class="grid grid-3" style="margin:16px 0 8px"><div><small class="subtle">Entry / Exit</small><div class="t-num">${t.entry.toFixed(5)} / ${t.exit.toFixed(5)}</div></div><div><small class="subtle">Stop / Target</small><div class="t-num">${t.sl.toFixed(5)} / ${t.tp.toFixed(5)}</div></div><div><small class="subtle">Exit reason</small><div>${esc(t.reason)}</div></div></div><p style="margin-top:10px"><small class="subtle">ENTRY PLAN</small><br>${esc(t.thesis)}</p><div class="field"><label for="reflection-${t.id}">Posttrade reflection (minimum 15 characters for journal credit)</label><textarea id="reflection-${t.id}" rows="3" placeholder="Did I follow the plan? What did I learn?">${esc(t.reflection||'')}</textarea></div><button class="btn sm" style="margin-top:11px" data-action="save-reflection" data-id="${t.id}">Save review</button></article>`).join('')}</div>`}`;}
function performance(){const p=perf();const last=data.balanceHistory;return `<div class="section-heading" style="margin-top:0"><div><div class="eyebrow">Performance analytics</div><h1>Review the distribution, not the last trade.</h1><p class="muted">Statistics come only from your synthetic practice trades.</p></div></div><div class="grid grid-4">${metric('Total simulated P&L',`<span class="${valueClass(p.pnl)}">${fmt(p.pnl)}</span>`,'Closed practice orders','activity')}${metric('Win rate',`${p.winRate}%`,`${p.wins} wins · ${p.losses} losses`,'target')}${metric('Expectancy / trade',fmt(p.expectancy),'Average net result per closed trade','calculator')}${metric('Max balance drawdown',pct(p.maxDD),'Peak-to-trough closed balance','shield')}</div><div class="grid grid-2" style="margin-top:18px"><div class="card"><h3>Balance history</h3><div id="equitySparkline" style="min-height:200px"></div><p class="caption">Realized balance only. Floating equity between trades is not charted.</p></div><div class="card"><h3>Process scorecard</h3><div class="kv"><span>Practice trades completed</span><strong>${p.count}</strong></div><div class="kv"><span>Trades with written reflections</span><strong>${p.journalled}</strong></div><div class="kv"><span>Reflection coverage</span><strong>${p.journalRate}%</strong></div><div class="kv"><span>Profit factor</span><strong>${p.profitFactor===null?'No losses recorded':p.profitFactor}</strong></div><div class="kv"><span>Worst balance drawdown</span><strong>${p.maxDD}%</strong></div><div class="divider"></div><p class="notice">Small samples do not establish a genuine advantage. A good backtest or synthetic practice result is not evidence of likely real-world profit.</p></div></div><div class="section-heading"><h2>Completed orders</h2></div><div class="card table-wrap">${!data.trades.length?'<div class="empty">No closed practice orders yet. Your statistics will appear here once you trade in the lab.</div>':`<table><thead><tr><th>Trade</th><th>Pair</th><th>Side</th><th>Lots</th><th>Exit reason</th><th>Result</th><th>R</th></tr></thead><tbody>${data.trades.slice().reverse().map((t,i)=>`<tr><td>#${data.trades.length-i}</td><td>${t.pair}</td><td>${t.side}</td><td>${t.lots.toFixed(2)}</td><td>${esc(t.reason)}</td><td class="${valueClass(t.pnl)}">${fmt(t.pnl)}</td><td>${L.round(t.pnl/t.risk,2)}</td></tr>`).join('')}</tbody></table>`}</div>`;}
function readiness(){const p=perf();const approved=[
  {ok:passed()===20,title:'Complete all 20 lessons',detail:`${passed()} / 20 lesson quizzes passed`,goal:'Reach at least 75% on each four-question quiz.'},
  {ok:!!data.exam&&data.exam.score>=85,title:'Pass final knowledge exam',detail:data.exam?`${data.exam.score}% final assessment`:'Not completed',goal:'Score at least 85% across 20 questions.'},
  {ok:data.plan.trim().length>=60,title:'Write a full trading plan',detail:`${data.plan.trim().length} characters written`,goal:'Record setup, limits, hours, and no-trade criteria.'},
  {ok:p.count>=30,title:'Complete 30 synthetic practice trades',detail:`${p.count} / 30 closed trades`,goal:'Document a repeatable process across outcomes.'},
  {ok:p.count>=30&&p.journalRate>=90,title:'Review at least 90% of trades',detail:`${p.journalRate}% reviewed`,goal:'Write a substantial posttrade reflection.'},
  {ok:p.count>=30&&p.maxDD<=8,title:'Keep demo drawdown at or below 8%',detail:`${p.maxDD}% worst realized drawdown`,goal:'Rehearse protecting capital. Monitor losses and stops.'}
];return approved;}
function assessment(){const checks=readiness();const count=checks.filter(x=>x.ok).length;const ready=count===checks.length;return `<div class="section-heading" style="margin-top:0"><div><div class="eyebrow">Mastery pathway</div><h1>Earn evidence of discipline.</h1><p class="muted">Course milestones are learning benchmarks, not financial accreditation or approval for live trading.</p></div><span class="chip ${ready?'teal':'orange'}">${count} / 6 milestones</span></div><div class="grid grid-2"><div class="card"><div class="inline-actions"><div class="score-circle" style="--pct:${count/6*100}%"><div>${count}/6</div></div><div><h2>${ready?'Training milestones met':'Your readiness checklist'}</h2><p class="muted">Master the terms, practice the process, and protect your simulated equity.</p></div></div><div class="readiness-grid" style="margin-top:22px">${checks.map(c=>`<div class="readiness-item ${c.ok?'done':''}"><span class="state-icon">${c.ok?icon('check'):'·'}</span><div><strong>${esc(c.title)}</strong><small>${esc(c.goal)}</small></div><span class="state-text">${esc(c.detail)}</span></div>`).join('')}</div></div><div class="card"><div class="eyebrow">Knowledge assessment</div><h2>Final exam</h2><p class="muted" style="margin:13px 0 17px">Twenty questions, one drawn from each lesson. Passing threshold: 17 of 20 correct. Retakes are available.</p>${data.exam?`<div class="result-box"><strong class="${data.exam.score>=85?'accent':'warning'}">Last score: ${data.exam.score}%</strong><p class="muted">${data.exam.score>=85?'Knowledge assessment passed.':'Review lessons you missed and try again.'}</p></div>`:''}${!examQuestions.length?`<button class="btn" data-action="start-exam">Start 20-question exam ${icon('arrow')}</button>`:`<div class="quiz">${examQuestions.map((item,i)=>{const q=item.question,sel=examDraft[i],review=examFeedback!==null;return `<div class="question"><h4>${i+1}. ${esc(q.question)}</h4><div class="options">${q.answers.map((a,j)=>`<button class="option ${review&&j===q.correct?'right':review&&sel===j&&j!==q.correct?'wrong':sel===j?'chosen':''}" data-exam-answer="${i}" data-opt="${j}" ${review?'disabled':''}>${String.fromCharCode(65+j)}. ${esc(a)}</button>`).join('')}</div>${review?`<p class="rationale">${esc(q.why)} · ${esc(item.lesson.title)}</p>`:''}</div>`;}).join('')}${examFeedback===null?`<button class="btn" data-action="grade-exam">Grade assessment</button>`:`<div class="result-box"><strong class="${examFeedback>=85?'accent':'warning'}">${examFeedback}% · ${examFeedback>=85?'Passed':'Not yet passed'}</strong><p class="muted">Review the explanations, then attempt another exam.</p><button class="btn secondary" data-action="start-exam">Retake assessment</button></div>`}</div>`}</div></div><div class="callout amber" style="margin-top:18px"><strong>After the app</strong><p style="margin-top:9px">Use an independent, regulated broker's live-price demo for a substantial additional period. Check actual spreads, commissions, news slippage, margin rules, and trading hours. Keep long-term savings and household expenses separate from speculative trading. Course completion does not establish that a live strategy is profitable.</p><a href="https://www.nfa.futures.org/basicnet/" rel="noopener noreferrer" target="_blank">Check broker records in NFA BASIC</a> · <a href="https://www.cftc.gov/LearnAndProtect/forexfrauds" target="_blank" rel="noopener noreferrer">CFTC forex investor information</a></div>`;}
function dictionary(){const found=glossary.filter(([t,d])=>[t,d].join(' ').toLowerCase().includes(glossaryTerm.toLowerCase()));return `<div class="section-heading" style="margin-top:0"><div><div class="eyebrow">Reference desk</div><h1>Forex dictionary.</h1><p class="muted">Learn the language before hearing it in an unfamiliar platform.</p></div></div><div class="field" style="max-width:470px;margin-bottom:20px"><label for="glossarySearch">Search ${glossary.length} definitions</label><input id="glossarySearch" value="${esc(glossaryTerm)}" placeholder="Search pip, margin, ATR, stop loss..."></div><div class="glossary-grid" id="glossaryResults">${found.map(([term,def])=>`<div class="glossary-card"><h4>${esc(term)}</h4><p>${esc(def)}</p></div>`).join('')||'<div class="empty">No matching term.</div>'}</div>`;}
function settings(){return `<div class="section-heading" style="margin-top:0"><div><div class="eyebrow">Your learning data</div><h1>Privacy and controls.</h1><p class="muted">${window.PipwiseCloud?.mode==='cloud'?'Progress syncs to your private cloud account when online. The administrator sees lesson, quiz, and practice activity.':'Progress stays in this browser until you export a backup. Sign in for cloud progress after setup.'}</p></div></div><div class="grid grid-2"><div class="card"><h3>Back up your progress</h3><p class="muted">Export a JSON file with lessons, practice trades, reflections, balance, and the written plan. Import it later on the same or a different device.</p><div class="inline-actions"><button class="btn" data-action="export">${icon('download')} Export backup</button><label class="btn secondary" for="importFile">Import backup</label><input type="file" id="importFile" accept=".json,application/json" style="position:absolute;width:1px;height:1px;overflow:hidden;opacity:0" /></div><p class="caption" style="margin-top:15px">Import replaces the current account's progress, including its cloud copy if you are signed in.</p></div><div class="card"><h3>Reset your simulator</h3><p class="muted">Start over with a $10,000 demo balance and fresh synthetic data. Choose to reset only trading data or the entire learning account.</p><div class="inline-actions"><button class="btn red" data-action="reset-trades">Reset practice account</button><button class="btn ghost" data-action="reset-all">Reset everything</button></div></div><div class="card"><h3>App environment</h3><p class="notice">Works in a modern browser. Signed-in users sync learning data through Firebase when online. Guest progress stays on one browser. No bank connections, live prices, or real-money trades. Export backups before resetting data or using a new device.</p></div><div class="card"><h3>Official learning and regulation resources</h3><ul class="list-clean"><li><a href="https://www.cftc.gov/LearnAndProtect/AdvisoriesAndArticles/CustomerAdvisory_MustKnowForex.html" target="_blank" rel="noopener noreferrer">CFTC: Eight Things You Should Know Before Trading Forex</a></li><li><a href="https://www.cftc.gov/LearnAndProtect/forexfrauds" target="_blank" rel="noopener noreferrer">CFTC: Forex Frauds</a></li><li><a href="https://www.nfa.futures.org/basicnet/" target="_blank" rel="noopener noreferrer">NFA BASIC: Registration and disciplinary records</a></li></ul></div></div>`;}
function admin(){return `<div class="section-heading" style="margin-top:0"><div><div class="eyebrow">Private administrator workspace</div><h1>Student learning dashboard</h1><p class="muted">View registered students, lessons passed, demo practice and last cloud sync. Students control their own progress.</p></div><button class="btn secondary sm" data-action="refresh-admin">Refresh students</button></div><div id="adminRoot" class="card"><div class="empty">Loading student activity…</div></div>`;}
function render(){let main={dashboard,academy,lab,calculator,journal,analytics:performance,assessment,glossary:dictionary,settings,admin}[view]();document.getElementById('app').innerHTML=shell(main);window.PipwiseCloud?.updateStatus?.();if(view==='lab'){updateOrderSizing();requestAnimationFrame(drawChart);}if(view==='calculator')updateCalc();if(view==='analytics')drawEquity();if(view==='admin')window.PipwiseCloud?.renderAdmin?.(document.getElementById('adminRoot'));}
function updateOrderSizing(){const out=document.getElementById('orderSizing');if(!out)return;const stop=Number(document.getElementById('orderStop').value),target=Number(document.getElementById('orderTarget').value),risk=Number(document.getElementById('orderRisk').value),side=document.getElementById('orderSidePreview').value;
const pos=tradePreview(side,risk,stop,target);if(!pos||!Number.isFinite(target)||target<=0){out.innerHTML='<div class="warning">Choose valid risk, stop, and target settings.</div>';return;}const free=equity()-(data.open?.margin||0);const safe=pos.lots>0&&pos.margin<=free;
out.innerHTML=`<div class="kv"><span>Calculated position size</span><strong>${pos.lots.toFixed(2)} standard lots</strong></div><div class="kv"><span>Planned stop exposure</span><strong>${fmt(pos.actualRisk)} / ${fmt(pos.budget)}</strong></div><div class="kv"><span>Target payoff, before extra costs</span><strong>${fmt(pos.potentialReward)}</strong></div><div class="kv"><span>Target / stop distance</span><strong>${L.round(target/stop,2)} : 1</strong></div><div class="kv"><span>Initial margin at 20:1</span><strong>${fmt(pos.margin)}</strong></div>${safe?'<div class="caption">Size rounds down to prevent exceeding planned risk.</div>':'<div class="warning" style="font-size:12px">Trade blocked: size below 0.01 lot or insufficient margin.</div>'}`;}
function updateCalc(){const target=document.getElementById('calcResults');if(!target)return;const balance=Number(document.getElementById('calcBalance').value),risk=Number(document.getElementById('calcPct').value),stop=Number(document.getElementById('calcStop').value),pair=document.getElementById('calcPair').value;const pos=L.positionSize(balance,risk,stop,pair);if(!pos || !Number.isFinite(stop) || stop>2000){target.innerHTML='<p class="warning">Enter a valid equity balance, risk percentage, and stop distance.</p>';return;}target.innerHTML=`<div class="eyebrow">Calculated position size</div><div class="big">${pos.lots.toFixed(2)} <small style="font-size:20px">lots</small></div><div class="muted" style="margin-top:8px">${pos.lots>0?`Approximately ${(pos.lots*100000).toLocaleString()} base units`:'Below a 0.01-lot minimum. Skip the trade.'}</div><div class="divider"></div><div class="kv"><span>Maximum planned risk budget</span><strong>${fmt(pos.budget)}</strong></div><div class="kv"><span>Planned risk after rounding</span><strong>${fmt(pos.actualRisk)}</strong></div><div class="kv"><span>Risk as % of equity</span><strong>${pct(pos.riskPctActual)}</strong></div><div class="kv"><span>Pip value at size</span><strong>${fmt(L.pipValue(pos.lots,pair))}/pip</strong></div><div class="kv"><span>Position notional at illustrative rate</span><strong>${fmt(pos.lots*100000*L.PAIRS[pair].base)}</strong></div><div class="divider"></div><small>Calculation assumes a stop filled exactly at its price. Gaps and slippage can create larger losses.</small>`;}
function openTrade(side){if(data.open){toast('Close the current position first.');return;}if(sessionHalt()){toast('Your 2% session loss limit has paused new entries.');return;}if(data.market.index>=getCandles().length-1){toast('Start a new scenario to trade.');return;}
const risk=Number(document.getElementById('orderRisk').value),stop=Number(document.getElementById('orderStop').value),target=Number(document.getElementById('orderTarget').value),thesis=document.getElementById('tradeThesis').value.trim();
if(![risk,stop,target].every(Number.isFinite)||![.25,.5,1].includes(risk)||stop<5||stop>250||!Number.isInteger(stop)||target<5||target>500||!Number.isInteger(target)){toast('Use valid risk, stop and target settings.');return;}
if(thesis.length<12){toast('Write at least 12 characters explaining your trade.');return;}
if(!['ruleSetup','ruleEvent','ruleRisk'].every(id=>document.getElementById(id).checked)){toast('Confirm all three checklist items before entering.');return;}
const pos=tradePreview(side,risk,stop,target);if(!pos||pos.lots<.01){toast('Your chosen risk is too small for the minimum 0.01 lot. Skip this setup.');return;}
if(pos.margin>equity()){toast('Insufficient free equity for the required margin.');return;}
const p=L.PAIRS[data.market.pair].pip;
data.open={id:Date.now(),pair:data.market.pair,side,lots:pos.lots,entry:pos.entry,sl:L.round(pos.entry+(side==='BUY'?-1:1)*stop*p,5),tp:L.round(pos.entry+(side==='BUY'?1:-1)*target*p,5),risk:pos.actualRisk,margin:pos.margin,thesis,scenario:data.market.mode==='csv'?'Historical CSV':data.market.scenario,entryIndex:data.market.index,date:new Date().toLocaleDateString('en-US'),reflection:''};save();render();toast(`${side} opened in the synthetic practice market.`);
}
function closeTrade(exitPrice,reason){const t=data.open;if(!t)return;const price=L.round(exitPrice,5);const pnl=L.round((t.side==='BUY'?1:-1)*(price-t.entry)*100000*t.lots,2);const closed={...t,exit:price,pnl,reason,closeIndex:data.market.index};data.balance=L.round(data.balance+pnl);data.sessionPnL=L.round(data.sessionPnL+pnl);data.trades.push(closed);data.balanceHistory.push(data.balance);data.open=null;save();toast(`Demo position closed: ${fmt(pnl)} (${reason}).`);}
function nextBars(count){const all=getCandles();for(let k=0;k<count&&data.market.index<all.length-1;k++){data.market.index++;if(data.open){const exit=L.checkExit(data.open,candle(),spread(),data.market.mode==='csv'?'Range':data.market.scenario);if(exit)closeTrade(exit.price,exit.reason);}}
if(data.market.index===all.length-1&&data.open){const t=data.open;const marketClose=L.quote(candle().close,t.pair,spread());closeTrade(t.side==='BUY'?marketClose.bid:marketClose.ask,'Scenario ended');}save();render();}
function newScenario(){if(data.open){toast('Close your position before changing scenarios.');return;}const pair=document.getElementById('marketPair')?.value||data.market.pair;const scenario=document.getElementById('marketScenario')?.value||data.market.scenario;const mode=document.getElementById('marketSource')?.value||'synthetic';if(!L.PAIRS[pair]||!L.SCENARIOS.includes(scenario))return;if(mode==='csv'&&(!data.imported||data.imported.pair!==pair)){toast('Import an OHLC CSV for the selected currency pair first.');return;}data.market={pair,scenario,mode,seed:Math.floor(Math.random()*2147483646)+1,index:85};data.sessionStart=data.balance;data.sessionPnL=0;save();render();toast('New simulated session started. Previous trades remain in your journal.');}
function manualClose(){const t=data.open;if(!t)return;const q=L.quote(candle().close,t.pair,spread());closeTrade(t.side==='BUY'?q.bid:q.ask,'Manual close');render();}
function gradeQuiz(id){const lesson=lessons.find(l=>l.id===id);if(!lesson)return;const ans=quizDraft[id]||{};if(Object.keys(ans).length!==4){toast('Answer all four questions before grading.');return;}const correct=lesson.questions.filter((q,i)=>ans[i]===q.correct).length;const score=correct*25;quizFeedback[id]=score;if(score>=75){data.completed[id]=Math.max(data.completed[id]||0,score);save();}render();toast(score>=75?'Lesson passed. Progress saved.':'Review the explanations and retry.');}
function startExam(){examQuestions=lessons.map(l=>({lesson:l,question:l.questions[Math.floor(Math.random()*l.questions.length)]}));examDraft={};examFeedback=null;render();}
function gradeExam(){if(Object.keys(examDraft).length!==examQuestions.length){toast('Answer all 20 questions first.');return;}const n=examQuestions.filter((x,i)=>examDraft[i]===x.question.correct).length;examFeedback=n/20*100;if(!data.exam||examFeedback>data.exam.score)data.exam={score:examFeedback,date:new Date().toISOString()};save();render();toast(examFeedback>=85?'Knowledge exam passed.':'Review missed answers before retaking.');}
function drawChart(){const canvas=document.getElementById('priceChart');if(!canvas)return;const rect=canvas.getBoundingClientRect();const width=Math.round(rect.width),height=Math.round(rect.height);if(!width||!height)return;const dpr=Math.min(2,window.devicePixelRatio||1);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);ctx.clearRect(0,0,width,height);
const end=data.market.index,start=Math.max(0,end-(width<470?38:64)),series=getCandles().slice(start,end+1);const left=11,right=width-75,top=19,bottom=height-32;const vals=series.flatMap(c=>[c.high,c.low]);if(data.open)vals.push(data.open.entry,data.open.sl,data.open.tp);let min=Math.min(...vals),max=Math.max(...vals);const pad=Math.max((max-min)*.12,L.PAIRS[data.market.pair].pip*6);min-=pad;max+=pad;
const py=v=>top+(max-v)/(max-min)*(bottom-top);const step=(right-left)/Math.max(series.length,1);const px=i=>left+step*(i+.5);ctx.font='11px ui-sans-serif,system-ui';ctx.textBaseline='middle';
for(let n=0;n<=5;n++){const y=top+(bottom-top)*n/5;ctx.strokeStyle='#223248';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(right,y);ctx.stroke();ctx.fillStyle='#7990a8';ctx.fillText((max-(max-min)*n/5).toFixed(5),right+6,y);}
const moving=(span)=>{const all=getCandles(),values=[];let prev=all[0].close;const k=2/(span+1);for(let i=0;i<=end;i++){prev=i===0?all[i].close:all[i].close*k+prev*(1-k);values.push(prev);}return values.slice(start,end+1);};
const drawEMA=(length,color)=>{const arr=moving(length);ctx.strokeStyle=color;ctx.lineWidth=1.7;ctx.beginPath();arr.forEach((v,i)=>{if(i===0)ctx.moveTo(px(i),py(v));else ctx.lineTo(px(i),py(v));});ctx.stroke();};
const bw=Math.max(2,Math.min(9,step*.58));series.forEach((c,i)=>{const rising=c.close>=c.open;ctx.strokeStyle=ctx.fillStyle=rising?'#55d8b8':'#e8788e';const x=px(i);ctx.lineWidth=Math.max(1,bw*.18);ctx.beginPath();ctx.moveTo(x,py(c.high));ctx.lineTo(x,py(c.low));ctx.stroke();const a=py(c.open),b=py(c.close);ctx.fillRect(x-bw/2,Math.min(a,b),bw,Math.max(1.5,Math.abs(a-b)));});
drawEMA(50,'#7ba9ff');drawEMA(20,'#61e8bd');
if(data.open){const lines=[[data.open.entry,'#f4bd6c','ENTRY'],[data.open.sl,'#ff8b94','STOP'],[data.open.tp,'#57e4c3','TARGET']];for(const [v,color,label] of lines){const y=py(v);ctx.save();ctx.setLineDash([5,4]);ctx.strokeStyle=color;ctx.globalAlpha=.85;ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(right,y);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=color;ctx.font='bold 10px ui-sans-serif,system-ui';ctx.fillText(label,right-52,y-10);ctx.restore();}}
ctx.fillStyle='#8297ac';ctx.font='10px ui-sans-serif,system-ui';ctx.fillText(`BAR ${start+1}`,left,bottom+17);ctx.fillText(`BAR ${end+1}`,Math.max(left,right-54),bottom+17);
}
function drawEquity(){const node=document.getElementById('equitySparkline');if(!node)return;const arr=data.balanceHistory;if(arr.length<2){node.innerHTML='<div class="empty" style="margin-top:14px">Balance graph appears after your first closed trade.</div>';return;}const min=Math.min(...arr),max=Math.max(...arr),pad=(max-min)||1;const w=650,h=190;const points=arr.map((v,i)=>`${15+i/(arr.length-1)*(w-30)},${h-22-(v-min)/pad*(h-38)}`).join(' ');node.innerHTML=`<svg viewBox="0 0 ${w} ${h}" aria-label="Realized balance history" role="img" width="100%" height="190"><defs><linearGradient id="lineBg" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#57e4c3" stop-opacity=".23"/><stop offset="1" stop-color="#57e4c3" stop-opacity="0"/></linearGradient></defs><line x1="15" x2="635" y1="165" y2="165" stroke="#2a3a50" stroke-dasharray="4 4"/><polygon points="15,168 ${points} 635,168" fill="url(#lineBg)"/><polyline points="${points}" fill="none" stroke="#57e4c3" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><text x="15" y="15" fill="#a9bacd" font-size="13">High ${fmt(max)}</text><text x="15" y="184" fill="#a9bacd" font-size="13">Low ${fmt(min)}</text></svg>`;}
function backup(){const blob=new Blob([JSON.stringify({...data,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='pipwise-progress-backup.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported. Save it somewhere safe.');}
function importHistory(file){
if(!file)return;
if(data.open){toast('Close the open trade before importing a different market.');return;}
if(file.size>2_000_000){toast('CSV exceeds 2 MB. Use up to 2,000 OHLC rows.');return;}
const pair=document.getElementById('marketPair')?.value||data.market.pair;
const reader=new FileReader();reader.onload=()=>{try{
const raw=String(reader.result||'').replace(/^\uFEFF/,'');
const lines=raw.split(/\r?\n/).filter(l=>l.trim());if(lines.length<101)throw Error('Need at least 100 candles');
const delim=lines[0].includes(';')?';':',';
const cells=line=>{let values=[],token='',quoted=false;for(let i=0;i<line.length;i++){const ch=line[i];if(ch==='"'){if(quoted&&line[i+1]==='"'){token+='"';i++;}else quoted=!quoted;}else if(ch===delim&&!quoted){values.push(token.trim());token='';}else token+=ch;}values.push(token.trim());return values;};
const keys=cells(lines[0]).map(x=>x.toLowerCase().replace(/[<>_\s]/g,''));
const cols=['open','high','low','close'].map(k=>keys.indexOf(k));if(cols.some(i=>i<0))throw Error('Missing open/high/low/close columns');
const bars=[];
for(const line of lines.slice(1,2001)){const row=cells(line);const a=cols.map(n=>Number(row[n]));if(a.some(v=>!Number.isFinite(v)||v<=0))continue;const [open,high,low,close]=a;if(high<Math.max(open,close,low)||low>Math.min(open,close,high))continue;bars.push({open:L.round(open,5),high:L.round(high,5),low:L.round(low,5),close:L.round(close,5)});}
if(bars.length<100)throw Error('Not enough valid OHLC rows');
if(!confirm(`Import ${bars.length} historical OHLC candles as ${pair}? Choose the correct currency pair and use chronological CSV data.`))return;
data.imported={pair,name:file.name.slice(0,65),candles:bars};data.market={pair,scenario:'Range',mode:'csv',seed:0,index:85};data.sessionStart=data.balance;data.sessionPnL=0;save();render();toast(`${bars.length} historical candles imported for practice replay.`);
}catch(err){toast(`CSV not imported: ${err.message}`);}};reader.readAsText(file);
}
function resetTrades(){if(!confirm('Reset only your practice balance and trade journal? Lessons and exam will remain.'))return;data.balance=10000;data.balanceHistory=[10000];data.trades=[];data.open=null;data.market={pair:'EUR/USD',scenario:'Uptrend',mode:'synthetic',seed:101,index:85};data.sessionStart=10000;data.sessionPnL=0;save();render();toast('Practice account reset.');}
function resetAll(){if(!confirm('Erase all lessons, exam, journal, account, and plan in this browser? Export first if you need a backup.'))return;data=defaults();selectedLesson=lessons[0].id;quizDraft={};quizFeedback={};examQuestions=[];examDraft={};examFeedback=null;save();setView('dashboard');toast('Fresh local learning account created.');}
function importData(file){if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const x=JSON.parse(reader.result);if(x.version!==1||!Array.isArray(x.trades)||!Array.isArray(x.balanceHistory)||!x.market||!L.PAIRS[x.market.pair]||!L.SCENARIOS.includes(x.market.scenario)||!Number.isFinite(x.balance)||!x.completed||typeof x.completed!=='object')throw Error('Invalid backup');if(!confirm('Replace all current local progress with the selected backup?'))return;data={...defaults(),...x};delete data.exportedAt;save();setView('dashboard');toast('Backup imported.');}catch{toast('Import failed. Select a valid Pipwise JSON backup.');}};reader.readAsText(file);}
function handleClick(ev){const el=ev.target.closest('button[data-nav],button[data-lesson],button[data-stage],button[data-answer-lesson],button[data-exam-answer],button[data-action],button[data-filter]');if(!el)return;
if(el.dataset.nav){setView(el.dataset.nav);return;}
if(el.dataset.stage!==undefined){selectedLesson=lessons.find(l=>l.stage===Number(el.dataset.stage)).id;setView('academy');return;}
if(el.dataset.lesson){selectedLesson=el.dataset.lesson;setView('academy');return;}
if(el.dataset.answerLesson){const id=el.dataset.answerLesson;quizDraft[id]=quizDraft[id]||{};quizDraft[id][Number(el.dataset.q)]=Number(el.dataset.opt);render();return;}
if(el.dataset.examAnswer!==undefined){examDraft[Number(el.dataset.examAnswer)]=Number(el.dataset.opt);render();return;}
if(el.dataset.filter){currentJournalFilter=el.dataset.filter;render();return;}
const action=el.dataset.action,id=el.dataset.id;
if(action==='logout'){window.PipwiseCloud?.logout?.();return;}
if(action==='refresh-admin'){window.PipwiseCloud?.renderAdmin?.(document.getElementById('adminRoot'));return;}
if(action==='submit-quiz')gradeQuiz(id);
if(action==='retry-quiz'){delete quizFeedback[id];quizDraft[id]={};render();}
if(action==='start-exam')startExam();
if(action==='grade-exam')gradeExam();
if(action==='new-scenario')newScenario();
if(action==='next-bar')nextBars(Number(el.dataset.count)||1);
if(action==='open-trade')openTrade(el.dataset.side);
if(action==='close-trade')manualClose();
if(action==='save-plan'){const txt=document.getElementById('planInput')?.value||'';data.plan=txt.slice(0,12000);save();toast('Trading plan saved.');}
if(action==='save-reflection'){const t=data.trades.find(t=>String(t.id)===id);if(t){t.reflection=(document.getElementById('reflection-'+id)?.value||'').slice(0,10000);save();render();toast('Journal reflection saved.');}}
if(action==='export')backup();
if(action==='reset-trades')resetTrades();
if(action==='reset-all')resetAll();
}
document.addEventListener('click',handleClick);
document.addEventListener('change',ev=>{const id=ev.target?.id;if(id==='importFile')importData(ev.target.files[0]);if(id==='csvFile')importHistory(ev.target.files[0]);if(['orderRisk','orderStop','orderTarget','orderSidePreview'].includes(id))updateOrderSizing();if(['calcBalance','calcPct','calcStop','calcPair'].includes(id))updateCalc();});
document.addEventListener('input',ev=>{const id=ev.target?.id;if(['orderStop','orderTarget'].includes(id))updateOrderSizing();if(['calcBalance','calcStop'].includes(id))updateCalc();if(id==='glossarySearch'){glossaryTerm=ev.target.value;const out=document.getElementById('glossaryResults');if(out){const found=glossary.filter(([t,d])=>(t+' '+d).toLowerCase().includes(glossaryTerm.toLowerCase()));out.innerHTML=found.map(([term,def])=>`<div class="glossary-card"><h4>${esc(term)}</h4><p>${esc(def)}</p></div>`).join('')||'<div class="empty">No matching term.</div>';}}});
window.addEventListener('resize',()=>{if(view==='lab')drawChart();});
render();
})();
